"""Classify documents into invoice/other, move them, build invoices/summary.csv."""
import os, re, csv, glob, json, shutil
from decimal import Decimal

DOCS, INV, OTH = '/app/documents', '/app/invoices', '/app/other'
TEXT = json.load(open('/app/text.json'))

NUM = r'(?<![\d.,])\d{1,3}(?:[ .,]\d{3})*(?:[.,]\d{1,2})?(?![\d])'

def to_dec(s):
    s = s.replace('$', '').replace(' ', '').strip()
    m = re.search(r'([.,])(\d{1,2})$', s)
    if m:
        head = re.sub(r'[.,]', '', s[:m.start()])
        return Decimal(head or '0') + Decimal(m.group(2).ljust(2, '0')) / 100
    return Decimal(re.sub(r'[.,]', '', s) or '0')

def nums(line):
    line = re.sub(r'\d+\s?%', ' ', line)          # drop percentages
    line = re.sub(r'\b\d{2,4}-\d{2,4}-\d{2,4}\b', ' ', line)  # drop tax ids/dates
    return [to_dec(x) for x in re.findall(NUM, line)]

def is_invoice(text):
    return bool(re.search(r'\binvoice\b', text, re.I))

def extract(text):
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    total = vat = None

    # --- layout A: "gross worth" summary tables (VAT column present) ---
    if re.search(r'gross\s*worth', text, re.I):
        cash = [to_dec(m) for m in re.findall(r'\$\s?(' + NUM + ')', text)]
        for l in lines:                      # single-line summary: net / vat / gross
            if re.match(r'^total\b', l, re.I):
                n = nums(l)
                if len(n) >= 3:
                    total, vat = n[-1], n[-2]
        if total is None and cash:
            total = max(cash)
        if vat is None:                      # value(s) below a bare "VAT" header
            for i, l in enumerate(lines):
                if re.fullmatch(r'VAT', l, re.I):
                    for nxt in lines[i + 1:i + 4]:
                        n = nums(nxt)
                        if n:
                            vat = n[-1]
                            break
                    if vat is not None:
                        break
        return total, vat

    # --- layout B/C: label-driven ---
    grand = amount_due = None
    for l in lines:
        low, n = l.lower(), nums(l)
        if not n:
            continue
        if re.search(r'grand\s*total', low):
            grand = grand if grand is not None else max(n)
        elif re.search(r'total\s*price', low.replace('totalprice', 'total price')):
            total = total if total is not None else max(n)
        elif re.search(r'amount\s*due', low):
            amount_due = amount_due if amount_due is not None else max(n)
        elif re.search(r'\btotal\b', low):
            total = total if total is not None else max(n)
        if vat is None and re.search(r'\b(vat|tax|gst)\b', low) and not re.search(r'tax\s*id', low):
            n2 = nums(l)
            if n2:
                vat = n2[-1]
    if total is None and grand is None:      # value column detached from "Total:" label
        cash = [to_dec(m) for m in re.findall(r'\$\s?(' + NUM + ')', text)]
        if cash and re.search(r'^\s*total\s*:?\s*$', text, re.I | re.M):
            total = max(cash)
    chosen = grand if grand is not None else (total if total is not None else amount_due)
    return chosen, vat

def fmt(d):
    return '0.00' if d is None else f'{d:.2f}'

def main():
    os.makedirs(INV, exist_ok=True)
    os.makedirs(OTH, exist_ok=True)
    rows = []
    for f in sorted(glob.glob(os.path.join(DOCS, '*'))):
        name = os.path.basename(f)
        text = TEXT.get(name, '')
        if is_invoice(text):
            t, v = extract(text)
            rows.append([name, t or Decimal(0), v or Decimal(0)])
            shutil.move(f, os.path.join(INV, name))
        else:
            shutil.move(f, os.path.join(OTH, name))
    with open(os.path.join(INV, 'summary.csv'), 'w', newline='') as fh:
        w = csv.writer(fh)
        w.writerow(['filename', 'total_amount', 'vat_amount'])
        for name, t, v in rows:
            w.writerow([name, fmt(t), fmt(v)])
        w.writerow(['total', fmt(sum(r[1] for r in rows)), fmt(sum(r[2] for r in rows))])

if __name__ == '__main__':
    main()
